\title{Factor Blindness: Exact Zero Which-Factor Leakage of Trace-Routed
Batteries, and the Anatomy of a Plug-In Wall}
\author{Aristotle}
\date{20 September 2026}

\begin{document}
\maketitle

\begin{abstract}
A \emph{battery} is a cheap measurement device on ordered pairs of integers: a chain
of small modular fields, each recording the residues of the sum $p+q$ and the product
$pq$ of the pair, concatenated positionally into a single integer code. An empirical
programme reported that a four-field chained battery on moduli $[3,5,7,11]$ carried a
residual $0.0469$ bits of mutual information about \emph{which} of the two factors was
the larger one --- a small but nonzero apparent leak. A $200$-shuffle permutation null
returned a mean of $0.0469$ bits with standard deviation $0.0014$, placing the
observation $z=+0.05$ from its own null: the entire reading was estimator bias.
This paper replaces that empirical verdict by exact theorems. We prove
(i) \emph{exact factor blindness}: on any swap-closed, off-diagonal population of
ordered pairs, any symmetric readout has a contingency table that is exactly a product
table, hence exactly zero which-factor mutual information;
(ii) \emph{sharpness}: a zero plug-in reading holds if and only if the table is a
product table, and an asymmetric readout on the same population family is detected at a
full $1$ bit;
(iii) \emph{the sparse law}: when the code is injective on the sample, the plug-in
reading equals the label entropy exactly, its permutation null is a point mass, and the
$z$-score numerator vanishes identically;
(iv) \emph{capacity--leakage independence}: the chained code of moduli
$m_1,\dots,m_r$ is bounded by $\prod_i m_i^2$, giving an entropy ceiling of
$\log_2 1{,}334{,}025 \approx 20.35$ bits for the four-field battery;
(v) \emph{orbit blindness}: for any finite group $G$ acting on a population, any
$G$-invariant readout leaks exactly zero bits about any torsor coordinate of the action,
which recovers the two-factor wall as the case $|G|=2$ and settles the $k$-factor case
for $G=S_n$ with the ordering pattern as label; and
(vi) \emph{the arithmetic instance}: the ordered factorisations of $N$ form a
swap-closed population, off-diagonal exactly when $N$ is not a perfect square, so a
symmetric battery is exactly blind to cofactor order for every non-square $N$, in
particular for every semiprime $N=pq$ with $p \neq q$.
\end{abstract}

\noindent\textbf{Keywords:} factor blindness, mutual information, plug-in bias,
permutation null, Gibbs' inequality, symmetric functions, orbit blindness, divisor
involution.

\section{Introduction}

\subsection{The measurement problem}

Let $N = pq$ be a semiprime with $p \neq q$. A side-channel question, quite different
from the factoring problem itself, asks what cheap functions of the factor pair reveal.
A single bit is at stake: does a readout built from small modular fingerprints tell you
which of the two coordinates carries the larger factor?

Formally, fix a finite population $S \subset \mathbb{N}\times\mathbb{N}$ of ordered
pairs, a readout $c : \mathbb{N}\times\mathbb{N}\to K$ into a finite alphabet, and the
binary \emph{which-factor label}
\[
  \lab(p,q) \;=\; [\,p < q\,] \in \{\text{false},\text{true}\},
\]
true when the second coordinate is the bigger factor. The \emph{leakage} is the mutual
information between $\lab$ and $c$ under the uniform law on $S$.

\subsection{The empirical episode}

The device under test was the four-field chained battery on moduli $[3,5,7,11]$ of
\S\ref{sec:battery}. On thousands of ordered prime pairs, the plug-in estimate of the
leakage came back as $0.0469$ bits; a $200$-shuffle permutation null returned mean
$0.0469$, standard deviation $0.0014$, hence $z = +0.05$. A parallel two-field reading
of $0.0011$ bits was likewise inside its own null.

Two things are wrong with stopping there. First, a null-consistent reading is a
statement about the \emph{estimator}, not about the population. Second, a permutation
null with a very small spread is itself suspicious: it may indicate not a precise
measurement but a statistic that shuffling cannot move. This paper resolves both points:
the truth is exactly zero, for a structural reason, and the estimator's behaviour is
exactly what the theory predicts in the regime the experiment occupied.

\section{The battery and its trace routing}\label{sec:battery}

\begin{definition}[Chain step]
For a modulus $m \in \mathbb{N}$, a pair $x=(p,q)$ and an accumulator $a \in \mathbb{N}$,
\[
  \stepf_m(x,a) \;=\; \bigl(a\,m + (p+q) \bmod m\bigr)\,m + (pq)\bmod m .
\]
Each field contributes two base-$m$ digits: the residue of the \emph{trace} $p+q$ and
the residue of the \emph{norm} $pq$.
\end{definition}

\begin{definition}[Battery code]
For a list $\mathbf m = [m_1,\dots,m_r]$ the battery code is the left fold
$\code_{\mathbf m}(x) = \stepf_{m_r}(x,\cdots\stepf_{m_1}(x,0)\cdots)$. The
\emph{four-field battery} is $B_4 = \code_{[3,5,7,11]}$.
\end{definition}

\begin{theorem}[Trace routing]\label{thm:trace}
If $p+q = p'+q'$ and $pq = p'q'$ then $\code_{\mathbf m}(p,q) = \code_{\mathbf m}(p',q')$
for every list $\mathbf m$.
\end{theorem}

\begin{proof}[Proof sketch]
Induct on $\mathbf m$ with the accumulator generalised. Each step depends on the pair
only through $(p+q)\bmod m$ and $(pq)\bmod m$, which agree by hypothesis; the two chains
therefore enter the tail with equal accumulators.
\end{proof}

The content of Theorem~\ref{thm:trace} is that the battery reads only the coefficients of
the monic quadratic $X^2-(p+q)X+pq$ whose roots are $p$ and $q$: the Galois-invariant
part of the pair.

\begin{corollary}[Swap symmetry]\label{cor:swap}
$\code_{\mathbf m}(q,p) = \code_{\mathbf m}(p,q)$ for all $p,q$ and all $\mathbf m$.
\end{corollary}

\begin{theorem}[Alphabet bound]\label{thm:alphabet}
If every $m_i>0$ then $\code_{\mathbf m}(x) < \prod_{i=1}^r m_i^2$ for all $x$.
\end{theorem}

\begin{proof}[Proof sketch]
Induct with the stronger statement: if $a<A$ then the chain from $a$ is
$< A\prod_i m_i^2$. For one step,
$\stepf_m(x,a) = am^2 + \bigl((p+q \bmod m)m + (pq\bmod m)\bigr)$, and the bracket is
$<m^2$ since both residues are $<m$; hence $\stepf_m(x,a) < (a+1)m^2 \le Am^2$.
\end{proof}

For $[3,5,7,11]$ this gives $B_4(x) < (3\cdot5\cdot7\cdot11)^2 = 1{,}334{,}025$.

\section{Finite information theory}

All readings are in bits.

\begin{definition}
For a finite joint mass function $p : L\times K \to \mathbb{R}$ the margins are
$p_L(\ell)=\sum_k p(\ell,k)$ and $p_K(k)=\sum_\ell p(\ell,k)$. The \emph{plug-in mutual
information} is
\[
  I(p) \;=\; \sum_{\ell}\sum_{k} p(\ell,k)\,
    \log_2\frac{p(\ell,k)}{p_L(\ell)\,p_K(k)},
\]
with $0\log 0 = 0$. The \emph{entropy} of a mass function $r$ on $K$ is
$H(r) = -\sum_k r(k)\log_2 r(k)$.
\end{definition}

\begin{theorem}[Gibbs' inequality, plug-in form]\label{thm:gibbs}
Let $p$ be a probability vector on a finite index set, $q$ nonnegative with
$\sum_i q_i \le 1$, and $q_i = 0 \Rightarrow p_i = 0$. Then
$\sum_i p_i \log(p_i/q_i) \ge 0$.
\end{theorem}

\begin{proof}[Proof sketch]
For $p_i>0$, domination gives $q_i>0$ and $\log t \le t-1$ at $t=q_i/p_i$ yields
$-p_i\log(p_i/q_i)\le q_i-p_i$; for $p_i=0$ the bound reads $0\le q_i$. Summing gives
$-\sum_i p_i\log(p_i/q_i) \le \sum_i q_i - 1 \le 0$.
\end{proof}

\begin{theorem}[One-sidedness]\label{thm:nonneg}
If $p\ge 0$ and $\sum_{\ell,k}p(\ell,k)=1$ then $I(p)\ge 0$.
\end{theorem}

\begin{proof}[Proof sketch]
Apply Theorem~\ref{thm:gibbs} on $L\times K$ with the table as $p$ and the product of
its margins as $q$. Absolute continuity is automatic: a vanishing margin forces its whole
row or column of nonnegative entries to vanish. The product of margins has total mass~$1$.
\end{proof}

Theorem~\ref{thm:nonneg} is the mechanism of plug-in bias: the functional is bounded
below by its value at independence, so finite-sample noise can only push the reading up.

\begin{theorem}[Product tables read exactly zero]\label{thm:prodzero}
If $p(\ell,k)=p_L(\ell)p_K(k)$ for all $\ell,k$ then $I(p)=0$.
\end{theorem}

\begin{proof}[Proof sketch]
Cell by cell: either the cell is empty, contributing $0$, or the ratio inside the
logarithm is $1$.
\end{proof}

\begin{theorem}[Maximum-entropy ceiling]\label{thm:maxent}
For a probability vector $r$ on a nonempty finite $K$, $H(r)\le \log_2|K|$.
\end{theorem}

\begin{proof}[Proof sketch]
Apply Theorem~\ref{thm:gibbs} with the uniform comparison vector $q\equiv 1/|K|$.
\end{proof}

Both halves of the battery claim --- the nonnegativity that explains the bias and the
capacity ceiling --- descend from the single inequality $\log x \le x-1$.

\section{Exact factor blindness}

Fix a finite alphabet $K$, a finite population $S$ and a readout $c$.

\begin{definition}
The \emph{readout fiber} is $F_k=\{x\in S: c(x)=k\}$, the \emph{cell} is
$C_{b,k}=\{x\in S: c(x)=k,\ \lab(x)=b\}$, and the \emph{empirical joint law} is
$P(b,k)=|C_{b,k}|/|S|$.
\end{definition}

The population is \emph{swap-closed} if $x\in S \Rightarrow x^{\sw}\in S$, where
$(p,q)^{\sw}=(q,p)$, and \emph{off-diagonal} if no member has equal coordinates. The
readout is \emph{symmetric} if $c(x^{\sw})=c(x)$ for all $x$.

\begin{lemma}[Halving]\label{lem:halving}
Under these hypotheses $|C_{\mathrm{true},k}| = |C_{\mathrm{false},k}|$ for every $k$.
\end{lemma}

\begin{proof}[Proof sketch]
The map $x\mapsto x^{\sw}$ is an involution of $S$; it preserves the readout by symmetry,
hence maps each fiber to itself, and off the diagonal it flips the label. It is therefore
a self-inverse bijection $C_{\mathrm{true},k}\to C_{\mathrm{false},k}$.
\end{proof}

\begin{lemma}\label{lem:exhaust}
$|C_{\mathrm{true},k}|+|C_{\mathrm{false},k}| = |F_k|$ and $\sum_k |F_k| = |S|$.
\end{lemma}

\begin{proposition}[Product table]\label{prop:prod}
Under the same hypotheses $P(b,k)=P_L(b)P_K(k)$ for all $b,k$, where $P_K(k)=|F_k|/|S|$
and, on a nonempty population, $P_L(b)=1/2$.
\end{proposition}

\begin{proof}[Proof sketch]
Lemmas~\ref{lem:halving}--\ref{lem:exhaust} give $2|C_{b,k}|=|F_k|$. Summing over $k$
gives $P_L(b)=1/2$, whence
$P(b,k)=|C_{b,k}|/|S| = \tfrac12|F_k|/|S| = P_L(b)P_K(k)$. The empty population is
degenerate and the identity holds trivially.
\end{proof}

\begin{theorem}[Exact factor blindness]\label{thm:blind}
Let $S$ be swap-closed and off-diagonal and $c$ symmetric. Then $I(P)=0$ exactly.
\end{theorem}

\begin{proof}
Proposition~\ref{prop:prod} and Theorem~\ref{thm:prodzero}.
\end{proof}

\begin{corollary}\label{cor:b4}
On any swap-closed, off-diagonal population the which-factor leakage of $B_4$ is exactly
$0$ bits.
\end{corollary}

\begin{remark}[Non-vacuity]
On $S=\{(3,5),(5,3),(7,11),(11,7)\}$ one has $B_4(3,5)=B_4(5,3)=979345$ and
$B_4(7,11)=B_4(11,7)=400708$: the readout separates the two unordered pairs, carrying a
full bit of readout entropy, while leaking exactly $0$ about the label. The zero is not
the zero of a constant instrument.
\end{remark}

\section{Sharpness: the wall is exactly the product locus}

\begin{theorem}[Strict Gibbs]\label{thm:strict}
In the setting of Theorem~\ref{thm:gibbs}, if some index $i_0$ has $p_{i_0}>0$ and
$p_{i_0}\neq q_{i_0}$, then $\sum_i p_i\log(p_i/q_i)>0$.
\end{theorem}

\begin{proof}[Proof sketch]
The per-index bound is strict at $i_0$ because $\log t < t-1$ for $t>0$, $t\neq1$, and
$t=q_{i_0}/p_{i_0}\neq 1$.
\end{proof}

\begin{lemma}[Where the discrepancy must live]\label{lem:discrep}
Let $p,q$ be probability vectors with $p_{i_1}\neq q_{i_1}$ for some $i_1$. Then there is
an index $i$ with $p_i>0$ and $p_i\neq q_i$.
\end{lemma}

\begin{proof}[Proof sketch]
Otherwise $q_i-p_i\ge0$ pointwise while $\sum_i (q_i-p_i)=0$, forcing $p=q$ everywhere.
\end{proof}

Lemma~\ref{lem:discrep} is not a technicality: without it, strict Gibbs cannot be
applied, because the discrepancy could hide on the null set of $p$.

\begin{theorem}[Any deviation is seen]\label{thm:pos}
If $p\ge0$ has total mass $1$ and $p(\ell_1,k_1)\neq p_L(\ell_1)p_K(k_1)$ for some cell,
then $I(p)>0$.
\end{theorem}

\begin{theorem}[Equality case]\label{thm:iff}
For a nonnegative joint table of total mass $1$,
$I(p)=0 \iff p(\ell,k)=p_L(\ell)p_K(k)$ for all $\ell,k$.
\end{theorem}

\begin{theorem}[Label-entropy cap]\label{thm:cap}
For any nonnegative joint table,
\[
  I(p) - H(p_L) \;=\; \sum_{\ell,k}p(\ell,k)\log_2\frac{p(\ell,k)}{p_K(k)} \;\le\; 0,
\]
the right-hand side being the negated conditional entropy $-H(\lab \mid \mathrm{code})$;
in particular $I(p)\le H(p_L)$.
\end{theorem}

\begin{proof}[Proof sketch]
Split the logarithm as $\log_2(p/p_K) - \log_2 p_L$ on cells where $p>0$, sum the second
part over $k$ to recover $p_L$, and note each term $p\log_2(p/p_K)\le0$ since
$p(\ell,k)\le p_K(k)$.
\end{proof}

\begin{theorem}[The instrument has power]\label{thm:power}
Let $S=\{(3,5),(5,3)\}$, swap-closed and off-diagonal, and let $c=\lab$ be the readout
that publishes the which-factor label. Then $c$ is not symmetric and $I(P)=1$ bit.
\end{theorem}

\begin{corollary}[Dichotomy]
On the same population, the symmetric battery reads exactly $0$ bits and the asymmetric
readout exactly $1$ bit. Symmetry of the readout is load-bearing in
Theorem~\ref{thm:blind}.
\end{corollary}

\section{The sparse regime}

The experimental code was nearly injective on its sample: in a run of $3995$ ordered
prime pairs, $3597$ distinct four-field codes appeared.

\begin{definition}[Sparse table]
Let $\ell:\{1,\dots,n\}\to\{\text{false},\text{true}\}$ be the labels of a sample of size
$n$ whose $n$ code values are pairwise distinct, so each sample is its own code. The
empirical table is $T(b,i)=1/n$ if $\ell_i=b$ and $0$ otherwise. Write
$n_b=\#\{i:\ell_i=b\}$.
\end{definition}

\begin{theorem}[Sparse reading law]\label{thm:sparse}
$I(T) = H\bigl(b\mapsto n_b/n\bigr)$ exactly.
\end{theorem}

\begin{proof}[Proof sketch]
The code margin is uniform, $T_K(i)=1/n$, and the label margin is $T_L(b)=n_b/n$. Each
nonzero cell has value $1/n$ and ratio $n/n_b$, so the $b$-row contributes
$-\tfrac{n_b}{n}\log_2\tfrac{n_b}{n}$. Equivalently, injectivity makes
$H(\lab\mid\mathrm{code})=0$ and Theorem~\ref{thm:cap} becomes an equality.
\end{proof}

\begin{corollary}[The permutation null is a point mass]
$I(T_{\ell\circ\pi}) = I(T_\ell)$ for every permutation $\pi$ of the samples, since
relabelling preserves the counts $n_b$.
\end{corollary}

\begin{corollary}[The $z$-score numerator vanishes identically]
\[
  I(T_\ell) - \frac{1}{n!}\sum_\pi I(T_{\ell\circ\pi}) = 0,
  \qquad \max_\pi \bigl|I(T_{\ell\circ\pi}) - I(T_\ell)\bigr| = 0 .
\]
\end{corollary}

\begin{corollary}
$I(T_\ell)\le 1$ bit, with equality exactly at a balanced label margin.
\end{corollary}

Read together with Theorem~\ref{thm:blind}: the truth is $0$ bits because the readout is
symmetric; the reading is close to $1$ bit because the code is nearly injective and the
label margin balanced; the null sits at the same place because relabelling barely moves a
statistic of the label counts. A permutation null does not test ``is there a signal?'';
it tests ``does this statistic respond to relabelling?''

\begin{example}[The cleanest exact instance]
Let the population have the uniform table $U(\ell,k)=1/4$ on $2\times2$, with
$I(U)=0$. A two-sample yields the permutation-matrix table
$P_\sigma(\ell,k)=\tfrac12[\sigma(k)=\ell]$, and $I(P_\sigma)=1$ for both $\sigma\in S_2$:
observed $=$ null mean $=1$ bit, null variance $0$, truth $0$ bits. By
Theorem~\ref{thm:nonneg} the reading can never compensate downward.
\end{example}

\section{Capacity is not leakage}

\begin{theorem}\label{thm:ceiling4}
Any probability distribution on the alphabet of $B_4$ has entropy at most
$\log_2 1{,}334{,}025 \approx 20.35$ bits.
\end{theorem}

\begin{proof}
Theorem~\ref{thm:alphabet} gives the alphabet size and Theorem~\ref{thm:maxent} the
ceiling.
\end{proof}

Theorems~\ref{thm:blind} and~\ref{thm:ceiling4} are logically independent statements
about the same device. Numerically, on the $82{,}656$ ordered pairs of distinct primes in
$(50,2000)$, the empirical readout entropy of $B_4$ is $\approx 14.39$ bits --- all of it
symmetric trace-routed content. Lengthening the chain raises the ceiling and buys more
symmetric content; it buys no which-factor bits at any width.

\section{Orbit blindness: the general law}

\begin{setting}\label{set:orbit}
Let a finite group $G$ act on a finite set $X$, let $S\subseteq X$ be a finite $G$-stable
population, let $c:X\to K$ be $G$-invariant, and let $\lab : X \to L$ be a \emph{torsor
coordinate}: for every $x\in S$ and every $\ell\in L$ there is a unique $g\in G$ with
$\lab(g\cdot x)=\ell$.
\end{setting}

\begin{theorem}[Counting core]\label{thm:count}
In Setting~\ref{set:orbit}, $|G|\cdot|C_{\ell,k}| = |F_k|$ for all $\ell,k$.
\end{theorem}

\begin{proof}[Proof sketch]
Count $\{(x,g)\in F_k\times G : \lab(g\cdot x)=\ell\}$ twice. Fixing $x$, the torsor
property gives exactly one valid $g$, so the count is $|F_k|$. Fixing $g$, the map
$x\mapsto g\cdot x$ is a bijection of $F_k$ carrying
$\{x\in F_k:\lab(g\cdot x)=\ell\}$ onto $C_{\ell,k}$, so the count is $|G|\,|C_{\ell,k}|$.
\end{proof}

\begin{corollary}
$P_L(\ell)=1/|G|$ on a nonempty population, $P_K(k)=|F_k|/|S|$, and
$P(\ell,k)=P_L(\ell)P_K(k)$.
\end{corollary}

\begin{theorem}[Orbit blindness]\label{thm:orbit}
In Setting~\ref{set:orbit}, $I(P)=0$ exactly.
\end{theorem}

\begin{corollary}[Two-factor wall recovered]
Take $G=S_2$ acting by swap on a swap-closed, off-diagonal population with a symmetric
readout and the which-factor label. Off the diagonal, swapping flips the label, so
exactly one group element achieves any target label; Theorem~\ref{thm:orbit} reproduces
Theorem~\ref{thm:blind}.
\end{corollary}

\subsection{Many factors: the ordering pattern}

\begin{definition}[Rank and ordering pattern]
$S_n$ acts on tuples $v\in\mathbb{N}^{\{1,\dots,n\}}$ by $(\sigma\cdot v)_i =
v_{\sigma^{-1}(i)}$. For a tuple with pairwise distinct entries, the \emph{rank} of
coordinate $i$ is $\rk_v(i)=\#\{j : v_j<v_i\}$; injectivity makes $\rk_v$ a bijection of
the index set, and the \emph{ordering pattern} $\pat(v)\in S_n$ is that bijection.
\end{definition}

\begin{lemma}[Equivariance]\label{lem:equiv}
For injective $v$, $\pat(\sigma\cdot v) = \pat(v)\,\sigma^{-1}$.
\end{lemma}

\begin{lemma}[Torsor property]\label{lem:torsor}
For injective $v$ and any target $\ell\in S_n$, the unique $\sigma$ with
$\pat(\sigma\cdot v)=\ell$ is $\sigma=\ell^{-1}\pat(v)$.
\end{lemma}

\begin{theorem}[$S_n$-blindness]\label{thm:sn}
Let $S$ be a finite population of $n$-tuples with pairwise distinct entries, closed under
coordinate permutation, and let $c$ be any permutation-invariant readout into a finite
alphabet. Then the mutual information between the ordering pattern and $c$ over $S$ is
exactly $0$ bits --- for every $n$.
\end{theorem}

\begin{example}[Three-factor battery]
Let $S$ be the six orderings of $(3,5,7)$ and
$c(v)=\bigl(\sum_i v_i \bmod 13,\ \prod_i v_i \bmod 17\bigr)=(2,3)$, a permutation-invariant
readout. The population carries all six ordering patterns and the leakage is exactly $0$.
By contrast the non-invariant readout $v\mapsto v_1$ gives away
$\log_2 3 \approx 1.585$ of the $\log_2 6 \approx 2.585$ bits of ordering information.
\end{example}

\section{The arithmetic instance: divisor populations}

\begin{definition}
The \emph{ordered factorisations} of $N$ form $D(N)=\{(d,N/d) : d \mid N\}$.
\end{definition}

\begin{theorem}[Swap closure]\label{thm:swapclose}
For every $N$, $D(N)$ is swap-closed.
\end{theorem}

\begin{proof}[Proof sketch]
If $d\mid N$ and $N\neq0$ then $N/d \mid N$ and $N/(N/d)=d$: the swap of $(d,N/d)$ is the
member indexed by the divisor $N/d$. The statement is the involutivity of $d\mapsto N/d$
on the divisor lattice.
\end{proof}

\begin{theorem}[Off-diagonality $\iff$ non-square]\label{thm:nonsquare}
$D(N)$ is off-diagonal if and only if $N$ is not a perfect square.
\end{theorem}

\begin{proof}[Proof sketch]
A diagonal member is a divisor with $d=N/d$, i.e.\ $N=d^2$; conversely $N=d^2$ puts
$(d,d)$ in $D(N)$.
\end{proof}

\begin{theorem}[Flagship arithmetic statement]\label{thm:flagship}
For every non-square $N$ and every symmetric readout $c$ into a finite alphabet --- in
particular for the four-field battery $B_4$ --- the which-factor leakage over $D(N)$ is
exactly $0$ bits.
\end{theorem}

\begin{proof}
Theorems~\ref{thm:swapclose}, \ref{thm:nonsquare} and~\ref{thm:blind}.
\end{proof}

Every semiprime $N=pq$ with $p\neq q$ is a non-square, so
Theorem~\ref{thm:flagship} covers the factoring case of interest.

\begin{example}[Non-vacuity at $N=15$]
$D(15)=\{(1,15),(3,5),(5,3),(15,1)\}$ and $B_4(3,5)=979345 \neq 476194 = B_4(1,15)$: the
readout is non-constant on the population, yet the leakage is exactly $0$.
\end{example}

\begin{example}[Sharpness at squares]
$D(36)$ and $D(100)$ each have nine ordered factorisations including a diagonal one, and
the same readout leaks $0.1021871709\ldots$ bits; $D(49)=\{(1,49),(7,7),(49,1)\}$ leaks
$0.2516291674\ldots$ bits. The single swap-fixed pair destroys the exact halving, so
off-diagonality is a sharp boundary and not a technical convenience.
\end{example}

\section{Algorithms and numerics}

Evaluating $\code_{\mathbf m}$ costs $O(r)$ arithmetic operations and $O(1)$ memory:

\begin{verbatim}
function BATTERY_CODE(moduli m[1..r], pair (p,q)):
    acc <- 0
    for i in 1..r:
        s <- (p + q) mod m[i]
        t <- (p * q) mod m[i]
        acc <- (acc * m[i] + s) * m[i] + t
    return acc
\end{verbatim}

Exact population leakage is a single pass, $O(|S|)$ time:

\begin{verbatim}
function POPULATION_LEAKAGE(S, readout c):
    joint, margL, margK <- empty counters
    for x in S:
        b <- [x.1 < x.2];  k <- c(x)
        increment joint[b,k], margL[b], margK[k]
    I <- 0
    for (b,k) with joint[b,k] > 0:
        pjk <- joint[b,k]/|S|;  pb <- margL[b]/|S|;  pk <- margK[k]/|S|
        I <- I + pjk * log2( pjk / (pb*pk) )
    return I
\end{verbatim}

