import math
from typing import Callable, Dict, Hashable, Sequence, Tuple

Pair = Tuple[int, int]


def bigger_label(x: Pair) -> bool:
    """True when the SECOND coordinate carries the bigger factor."""
    return x[0] < x[1]


def exact_leakage(
    population: Sequence[Pair], readout: Callable[[Pair], Hashable]
) -> float:
    """Exact which-factor leakage, in bits, of a readout on a finite population.

    Builds the contingency table of (which-factor label, readout value) under the
    uniform law on the population and evaluates the plug-in mutual information.
    On a swap-closed, off-diagonal population with a symmetric readout the result is
    exactly 0: every readout fiber splits in half, so the table is a product table.
    """
    n = len(population)
    if n == 0:
        return 0.0
    joint: Dict[Tuple[bool, Hashable], int] = {}
    marg_lab: Dict[bool, int] = {}
    marg_code: Dict[Hashable, int] = {}
    for x in population:
        b, k = bigger_label(x), readout(x)
        joint[(b, k)] = joint.get((b, k), 0) + 1
        marg_lab[b] = marg_lab.get(b, 0) + 1
        marg_code[k] = marg_code.get(k, 0) + 1
    total = 0.0
    for (b, k), count in joint.items():
        pjk = count / n
        total += pjk * math.log2(pjk / ((marg_lab[b] / n) * (marg_code[k] / n)))
    return total


def halving_certificate(
    population: Sequence[Pair], readout: Callable[[Pair], Hashable]
) -> Dict[str, object]:
    """Check the three hypotheses and the fiber-halving conclusion."""
    members = set(population)
    fibers: Dict[Hashable, Tuple[int, int]] = {}
    for x in population:
        t, f = fibers.get(readout(x), (0, 0))
        fibers[readout(x)] = (t + 1, f) if bigger_label(x) else (t, f + 1)
    return {
        "swap_closed": all((q, p) in members for (p, q) in population),
        "off_diagonal": all(p != q for (p, q) in population),
        "symmetric": all(readout((q, p)) == readout((p, q)) for (p, q) in population),
        "all_fibers_halved": all(t == f for t, f in fibers.values()),
        "leakage_bits": exact_leakage(population, readout),
    }

import math
import random
from typing import Dict, Hashable, List, Sequence, Tuple


def plugin_mutual_information(
    samples: Sequence[Tuple[Hashable, Hashable]]
) -> float:
    """Plug-in mutual information, in bits, of a list of (label, code) observations."""
    n = len(samples)
    if n == 0:
        return 0.0
    joint: Dict[Tuple[Hashable, Hashable], int] = {}
    ml: Dict[Hashable, int] = {}
    mk: Dict[Hashable, int] = {}
    for lab, code in samples:
        joint[(lab, code)] = joint.get((lab, code), 0) + 1
        ml[lab] = ml.get(lab, 0) + 1
        mk[code] = mk.get(code, 0) + 1
    return sum(
        (c / n) * math.log2((c / n) / ((ml[lab] / n) * (mk[code] / n)))
        for (lab, code), c in joint.items()
    )


def label_entropy(labels: Sequence[Hashable]) -> float:
    n = len(labels)
    counts: Dict[Hashable, int] = {}
    for b in labels:
        counts[b] = counts.get(b, 0) + 1
    return -sum((c / n) * math.log2(c / n) for c in counts.values())


def permutation_test(
    samples: Sequence[Tuple[Hashable, Hashable]],
    shuffles: int = 200,
    seed: int = 0,
) -> Dict[str, float]:
    """Permutation test WITH a sparsity guard.

    Returns the observed plug-in reading, the mean and sd of the relabelling null, the
    z-score, the label entropy, and the fraction of samples carrying a unique code.
    If that fraction is close to 1 the test has no power: the reading is then a
    function of the label counts alone, every relabelling reproduces it, and the null
    degenerates to a point mass, so the z-score is a ratio of vanishing quantities.
    """
    rng = random.Random(seed)
    labels = [lab for lab, _ in samples]
    codes = [code for _, code in samples]
    n = len(samples)
    observed = plugin_mutual_information(samples)
    readings: List[float] = []
    for _ in range(shuffles):
        shuffled = labels[:]
        rng.shuffle(shuffled)
        readings.append(plugin_mutual_information(list(zip(shuffled, codes))))
    mean = sum(readings) / len(readings)
    sd = math.sqrt(sum((r - mean) ** 2 for r in readings) / len(readings))
    unique_fraction = len(set(codes)) / n
    return {
        "observed_bits": observed,
        "null_mean_bits": mean,
        "null_sd_bits": sd,
        "z": (observed - mean) / sd if sd > 1e-15 else float("nan"),
        "label_entropy_bits": label_entropy(labels),
        "unique_code_fraction": unique_fraction,
        "test_has_power": unique_fraction < 0.5,
    }
